use serde_json::{Value, Map};
use std::collections::HashMap;

pub fn solve(input: Value) -> Value {
    if let Value::Array(arr) = input {
        if arr.is_empty() {
            return Value::Null;
        }

        let mut counts = HashMap::new();
        for item in arr {
            if let Value::String(s) = item {
                *counts.entry(s).or_insert(0) += 1;
            }
        }

        let mut most_frequent: Option<&String> = None;
        let mut max_count = 0;

        for (s, &count) in counts.iter() {
            if count > max_count || (count == max_count && most_frequent.map_or(true, |mf| s < mf)) {
                most_frequent = Some(s);
                max_count = count;
            }
        }

        most_frequent.map_or(Value::Null, |s| Value::String(s.clone()))
    } else {
        Value::Null
    }
}
